PRAGMA foreign_keys=ON;
CREATE TABLE users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,onboarded INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT (datetime('now')),updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE user_preferences(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,niche TEXT,language TEXT DEFAULT 'en',timezone TEXT DEFAULT 'UTC',default_platforms TEXT DEFAULT 'youtube,instagram',updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE connected_accounts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,platform TEXT NOT NULL CHECK(platform IN('youtube','instagram')),external_id TEXT,display_name TEXT,token_cipher TEXT,scopes TEXT,status TEXT NOT NULL DEFAULT 'connected' CHECK(status IN('connected','disconnected','attention_required')),created_at TEXT NOT NULL DEFAULT (datetime('now')),updated_at TEXT NOT NULL DEFAULT (datetime('now')),UNIQUE(user_id,platform));
CREATE TABLE videos(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,file_name TEXT NOT NULL,content_type TEXT NOT NULL,size_bytes INTEGER,duration_s REAL,r2_key TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING_UPLOAD' CHECK(status IN('PENDING_UPLOAD','UPLOADED','PROCESSING','ANALYZED','METADATA_READY','SCHEDULED','PUBLISHING','PUBLISHED','FAILED','RETRY_PENDING')),created_at TEXT NOT NULL DEFAULT (datetime('now')),updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX idx_videos_user ON videos(user_id,created_at DESC);
CREATE TABLE video_analysis(id TEXT PRIMARY KEY,video_id TEXT NOT NULL REFERENCES videos(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'QUEUED' CHECK(status IN('QUEUED','RUNNING','DONE','FAILED')),result_json TEXT,error TEXT,provider TEXT,created_at TEXT NOT NULL DEFAULT (datetime('now')),updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE transcripts(id TEXT PRIMARY KEY,video_id TEXT NOT NULL REFERENCES videos(id) ON DELETE CASCADE,user_id TEXT NOT NULL,language TEXT,body TEXT,created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE trend_research(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,platform TEXT,query TEXT,results_json TEXT,source_url TEXT,checked_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE generated_metadata(id TEXT PRIMARY KEY,video_id TEXT NOT NULL REFERENCES videos(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,platform TEXT NOT NULL CHECK(platform IN('youtube','instagram')),title TEXT,body TEXT,hashtags TEXT,source TEXT NOT NULL DEFAULT 'manual' CHECK(source IN('manual','ai')),created_at TEXT NOT NULL DEFAULT (datetime('now')),updated_at TEXT NOT NULL DEFAULT (datetime('now')),UNIQUE(video_id,platform));
CREATE TABLE metadata_versions(id TEXT PRIMARY KEY,metadata_id TEXT NOT NULL REFERENCES generated_metadata(id) ON DELETE CASCADE,snapshot_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE scheduled_posts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,video_id TEXT NOT NULL REFERENCES videos(id) ON DELETE CASCADE,platform TEXT NOT NULL,publish_at TEXT NOT NULL,timezone TEXT NOT NULL DEFAULT 'UTC',created_at TEXT NOT NULL DEFAULT (datetime('now')),UNIQUE(video_id,platform));
CREATE TABLE publishing_jobs(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,video_id TEXT NOT NULL REFERENCES videos(id) ON DELETE CASCADE,platform TEXT NOT NULL CHECK(platform IN('youtube','instagram')),idempotency_key TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'SCHEDULED' CHECK(status IN('SCHEDULED','PUBLISHING','PUBLISHED','FAILED','RETRY_PENDING')),run_at TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,max_attempts INTEGER NOT NULL DEFAULT 3,external_id TEXT,error TEXT,created_at TEXT NOT NULL DEFAULT (datetime('now')),updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX idx_jobs_due ON publishing_jobs(status,run_at);
CREATE TABLE publishing_logs(id TEXT PRIMARY KEY,job_id TEXT NOT NULL REFERENCES publishing_jobs(id) ON DELETE CASCADE,level TEXT NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE analytics_snapshots(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,video_id TEXT,platform TEXT NOT NULL,metrics_json TEXT NOT NULL,captured_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,message TEXT NOT NULL,read INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE automation_settings(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,paused INTEGER NOT NULL DEFAULT 0,manual_approval INTEGER NOT NULL DEFAULT 1,daily_limit INTEGER NOT NULL DEFAULT 3,paused_platforms TEXT DEFAULT '',updated_at TEXT NOT NULL DEFAULT (datetime('now')));
